const d=$json;
const esc=s=>String(s??'No informado').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label)=>'<a href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">'+esc(label)+'</a>';
let titulo,mensaje;
if(['BUSQUEDA_COMPLETA','BUSQUEDA_PARCIAL'].includes(d.resultado)){
 const rows=d.oportunidades??[];
 titulo=rows.length?'Oportunidades para revisar':'Sin coincidencias en esta búsqueda';
 mensaje='Empresa: '+esc(d.razonSocial)+'<br>RUC: '+esc(d.ruc)+'<br>Consulta de la fuente: '+esc(d.fechaConsultaFuente)+'<br>Palabras utilizadas: '+esc((d.terminos??[]).join(', '))+'<br><br>';
 if(!rows.length)mensaje+='No encontramos coincidencias con estos productos, regiones y plazos en el módulo consultado. Esto no significa que no existan otras convocatorias. Revisa el perfil o el buscador oficial.<br>';
 for(const o of rows){
  mensaje+='<hr><strong>'+esc(o.nomenclatura)+'</strong><br>'+esc(o.descripcion)+'<br>Entidad: '+esc(o.entidad)+'<br>Región de los ítems: '+esc((o.regionItems??[]).join(', ')||'Por verificar')+'<br>'+esc(o.motivo)+'<br>Inscripción hasta: '+esc(o.inscripcionHasta)+'<br>'+esc(o.estadoPlazo)+'<br>Presentación de ofertas: '+esc(o.presentacionOferta)+'<br>Monto publicado: '+esc(o.monto)+' '+esc(o.moneda)+'<br>'+link(o.url,'Ver ficha oficial');
  for(const b of (o.bases??[]))mensaje+=' · '+link(b.url,'Abrir bases');
  mensaje+='<br>';
 }
 for(const a of d.advertencias??[])mensaje+='<br>'+esc(a);
 mensaje+='<br><br>Se muestran hasta 10 oportunidades. Coincidencia inicial por palabras, no evaluación de aptitud ni probabilidad de ganar. Confirma requisitos y cronograma en la ficha oficial. Las bases están enlazadas; su contenido todavía no se analiza.<br>'+link(d.fuente,'Buscador oficial SEACE');
}else if(d.resultado==='PERFIL_NO_ENCONTRADO'){
 titulo='Primero registra el perfil';mensaje='No hay un perfil guardado para este RUC. Completa la fase 0 antes de buscar convocatorias.';
}else if(d.resultado==='PERFIL_SIN_TERMINOS'){
 titulo='Describe mejor tus productos';mensaje='Indica productos o servicios concretos en el perfil. Por ejemplo: muebles, colchones o mantenimiento de equipos.';
}else if(d.resultado==='FORMATO_INVALIDO'){
 titulo='Revisa el RUC';mensaje='Escribe exactamente 11 dígitos.';
}else{
 titulo='No se pudo completar la búsqueda';mensaje='El servicio local o la fuente oficial no respondieron correctamente. Esto no significa que no existan oportunidades. Puedes volver a intentar la fase 1.';
}
return [{json:{...d,titulo,mensaje}}];
